\label{asmpt:noise}
    At any time $t \geq 1$, the stochastic quantities satisfy the following.
    \vspace{-0.5em}
    \begin{enumerate}[leftmargin=*, label=\arabic*.]\setlength\itemsep{0.25em}
        \item The random samples $\{\xi^k_i \}_{i \in [n],k \in [t]}$ are independent across agents and iterations. 

        \item The noise at each agent is conditionally zero-mean, i.e., $\mathbb{E}[z^t_i \: \vert \: \mathcal{F}_t ] = 0$, for all $i \in [n]$.

        \item The noise at each agent has bounded $p$-th moment, $p \in (1,2]$, i.e., $\mathbb{E}\big[\|z^t_i\|^p \: \vert \: \mathcal{F}_t \big] \leq \sigma_i^p$, for all $i \in [n]$.
    \end{enumerate}

\label{lm:noise-behavior}
    Let $X_1,\ldots,X_n \in \mathbb{R}^d$ be independent random vectors and let $\widetilde{X}_i = \texttt{clip}(X_i)$, $i \in [n]$, with $\widetilde{X} = \frac{1}{n}\sum_{i \in [n]}\widetilde{X}_i$. If for some $p \in (1,2]$ and all $i \in [n]$ we have $\mathbb{E}\|X_i - \mathbb{E}[X_i]\|^p \leq \sigma_i^p$ and $\|\mathbb{E}[X_i]\| \leq \nicefrac{\gamma}{2}$, then
    \begin{align*}
        \mathbb{E}\|\widetilde{X} - \mathbb{E}[\widetilde{X}]\|^2 \leq \frac{18\gamma^{2-p}}{n^2}\sum_{i \in [n]}\sigma_i^p.
    \end{align*}

\label{lm:descent-inequality}
    If Assumption \ref{asmpt:cost} holds and $\alpha \leq \frac{1}{2L}$, then for any $t \geq 1$
    \begin{align*}
        f(&\overline{x}^{t+1}) \leq f(\overline{x}^t) - \frac{\alpha}{4}\|\nabla f(\overline{x}^t)\|^2 - \alpha\langle \nabla f(\overline{x}^t), \widehat{g}^t_u\rangle \\ 
        &+ 2\alpha^2L\|\widehat{g}^t_u\|^2 + 2\alpha\|\widehat{g}^t_b\|^2 + \frac{\alpha L^2}{2n}\sum_{i \in [n]}\|x^t_i - \overline{x}^t\|^2. 
    \end{align*}

\label{lm:consensus-crude}
    If Assumptions \ref{asmpt:network} and \ref{asmpt:initialization} hold, then for all $i \in [n]$ and any $t \geq 1$ 
    \begin{align*}
        &\|x^{t+1}_i - \overline{x}^{t+1}\| \leq \frac{\alpha\gamma\lambda\sqrt{n}}{1-\lambda}.
    \end{align*}

\label{lm:consensus-bound}
    If Assumptions \ref{asmpt:network}-\ref{asmpt:bdd-het} hold, then for all $t \geq 1$
    \begin{align*}
        &\frac{1}{n}\sum_{i \in [n]}\|x^{t+1}_i - \overline{x}^{t+1}\|^2 \leq \frac{8\alpha^2\lambda^2A^2}{(1-\lambda^2)}\sum_{k = 1}^t\bigg(\frac{1+\lambda^2}{2}\bigg)^{t-k} \\
        &+ \frac{8\alpha^2\lambda^2B^2}{n(1-\lambda^2)}\sum_{k = 1}^t\bigg(\frac{1+\lambda^2}{2}\bigg)^{t-k}\sum_{i \in [n]}\|\nabla f(x^k_i)\|^2 \\
        &+ \frac{8\alpha^2\lambda^2}{n(1-\lambda^2)}\sum_{k = 1}^t\bigg(\frac{1+\lambda^2}{2}\bigg)^{t-k}\sum_{i \in [n]}\big(\|\widetilde{g}^k_{i,b}\|^2 + \|\widetilde{g}^k_{i,u}\|^2\big).
    \end{align*}

\label{thm:non-cvx-hp}
    Let Assumptions \ref{asmpt:network}-\ref{asmpt:noise} hold. If for any $T \geq 1$ and $\delta \in (0,1)$, the clipping radius and the step-size are chosen as $\gamma = \max\Big\{2A + 4B\sqrt{L\Delta_1} + \frac{2\lambda L\sqrt{n}}{1-\lambda}, (nT)^{\frac{1}{3p-2}} \Big\}$ and $\alpha = \min\Big\{\frac{1}{2L}, \frac{1-\lambda^2}{8\lambda LB\sqrt{3}}, \frac{1-\lambda^2}{\lambda L\sqrt{6}}, \frac{(1-\lambda^2)^2}{6\lambda^2L}, \frac{(1-\lambda^2)^{2/3}\Delta_1^{1/3}}{2(\lambda LA)^{2/3}T^{1/3}\sqrt[3]{12}}, \frac{C_1}{\gamma}, \frac{C_2}{\gamma}n^{\frac{2p-1}{3p-2}}T^{\frac{1-p}{3p-2}}, \frac{C_3}{\gamma^{2/3}}n^{\frac{p}{3(3p-2)}}T^{\frac{2(1-p)}{3(3p-2)}} \Big\}$, with $C_1 = \min\Big\{1,\frac{3\sqrt{\Delta_1/2L}}{64\log\big(\frac{6T}{\delta}\big)}\Big\}$, $C_2 = \min\Big\{\frac{\Delta_1}{64\sigma^{2p}}, \frac{\sqrt{\Delta_1/2L}}{192\log\big(\frac{6T}{\delta}\big)\sigma^{p/2}} \Big\}$ and $C_3 = \frac{\Delta_1^{1/3}(1-\lambda^2)^{2/3}}{12\sigma^{p/3}\lambda^{2/3}L^{2/3}}$, then with probability at least $1 - \delta$
    \begin{align*}
        \frac{1}{nT}\sum_{t \in [T]}\sum_{i \in [n]}\|\nabla f(x^t_i)\|^2 = \widetilde{\mathcal{O}}\bigg((nT)^{\frac{2(1-p)}{3p-2}}\bigg),
    \end{align*} where $\widetilde{\mathcal{O}}(\cdot)$ hides terms of higher-order in $T$.

\label{thm:non-cvx-ie}
    Let Assumptions \ref{asmpt:network}-\ref{asmpt:noise} hold. If for any $T \geq 2$ the clipping radius and the step-size are chosen as $\gamma = \max\Big\{2A + 4B\sqrt{L\Delta_1} + \frac{2\lambda L\sqrt{n}}{1-\lambda}, (nT)^{\frac{1}{3p-2}} \Big\}$ and $\alpha = \min\Big\{\frac{1}{2L}, \frac{1-\lambda^2}{8\lambda LB\sqrt{3}}, \frac{1-\lambda^2}{\lambda L\sqrt{6}}, \linebreak \frac{(1-\lambda^2)^2}{6\lambda^2L}, \frac{(1-\lambda^2)^{2/3}\Delta_1^{1/3}}{2(\lambda LA)^{2/3}T^{1/3}\sqrt[3]{12}}, \frac{C_1}{\gamma}, \frac{C_2}{\gamma}n^{\frac{2p-1}{3p-2}}T^{\frac{1-p}{3p-2}}, \frac{\Delta_1^{1/3}(1-\lambda^2)^{2/3}}{12\sigma^{p/3}\gamma^{2/3}\lambda^{2/3}L^{2/3}}n^{\frac{p}{3(3p-2)}}T^{\frac{2(1-p)}{3(3p-2)}}\Big\}$, where $C_1 = \linebreak \min\Big\{1,\frac{3\sqrt{\Delta_1/2L}}{64\log(6n^4T^5)}\Big\}$ and $C_2 = \min\Big\{\frac{\Delta_1}{64\sigma^{2p}},\frac{\sqrt{\Delta_1/2L}}{192\log(6n^4T^5)\sigma^{p/2}} \Big\}$, it then holds that
    \begin{align*}
        \frac{1}{nT}\sum_{t \in [T]}\sum_{i \in [n]}\mathbb{E}\|\nabla f(x^t_i)\|^2 = \widetilde{\mathcal{O}}\bigg((nT)^{\frac{2(1-p)}{3p-2}}\bigg),
    \end{align*} where $\widetilde{\mathcal{O}}(\cdot)$ hides terms of higher-order in $T$.

\label{lm:sadiev}
    Let $X \in \mathbb{R}^d$ be a random vector and let $x = \mathbb{E}[X]$ and $\widetilde{X} = \texttt{clip}(X)$ be its expectation and clipped version. If for some $\sigma > 0$ and $p \in (1,2]$ we have $\mathbb{E}\|X - x\|^p \leq \sigma^p$ and $\|x\| \leq \nicefrac{\gamma}{2}$, then
    \begin{align}
        &\|\mathbb{E}[\widetilde{X}] - x\| \leq \frac{4\sigma^p}{\gamma^{p-1}}, \label{eq:bias-bdd} \\
        &\mathbb{E}\|\widetilde{X} - \mathbb{E}[\widetilde{X}]\|^2 \leq 18\gamma^{2-p}\sigma^p. \label{eq:variance-bdd}
    \end{align}

