\label{rmk:consensus}
    Note that Lemma \ref{lm:consensus-crude} implies the following bound on the average consensus gap
    \begin{equation*}
        \frac{1}{n}\sum_{i \in [n]}\|x^t_i - \overline{x}^t\|^2 \leq \frac{\alpha^2\gamma^2\lambda^2n}{(1-\lambda)^2}.
    \end{equation*} While nice and simple, the main issue in this bound stems from the coupling of the step-size and clipping radius of the same order, namely $\alpha^2\gamma^2$. From the choice of the step-size in Theorem \ref{thm:non-cvx-hp}, specifically $\alpha \leq \frac{C_2}{\gamma}n^{\frac{2p-1}{3p-2}}T^{\frac{1-p}{3p-2}}$ for a problem-related constant $C_2 > 0$, it follows that
    \begin{equation*}
        \frac{\alpha^2\gamma^2\lambda^2n}{(1-\lambda)^2} = \mathcal{O}\Bigg(\frac{n^{\frac{7p-4}{3p-2}}T^{\frac{2(1-p)}{3p-2}}}{(1-\lambda)^2} \Bigg).
    \end{equation*} While the above quantity on the right-hand side matches the decay of the leading term in Theorem \ref{thm:non-cvx-hp} with respect to $T$, it strictly grows in $n$. As such, naively using the bound from Lemma \ref{lm:consensus-crude} in the rest of the analysis would result in a term which matches the leading one in $T$ but increases in $n$, destroying the linear speed-up, and propagating the network effect to the leading term (via $(1-\lambda)^{-2}$). On the other hand, ignoring some terms for simplicity, Lemma \ref{lm:consensus-bound} results in the following bound
    \begin{equation*}
        \frac{1}{n}\sum_{i \in [n]}\|x^t_i - \overline{x}^t\|^2 = \mathcal{O}\bigg(\frac{\alpha^2}{n}\sum_{i \in [n]}\big(\|\widetilde{g}^k_{i,b}\|^2 + \|\widetilde{g}^k_{i,u}\|^2\big)\bigg). 
    \end{equation*} When agents' gradients are sufficiently small, i.e., when $\|\nabla f_i(x^t_i)\| \leq \frac{\gamma}{2}$, we can use Lemma \ref{lm:sadiev} to get
    \begin{equation*}
        \frac{1}{n}\sum_{i \in [n]}\|x^t_i - \overline{x}^t\|^2 = \mathcal{O}\Big(\alpha^2\gamma^{2-p} + \alpha^2\gamma^{2(1-p)}\Big) = \mathcal{O}\Big(\alpha^2\gamma^{2-p}\Big). 
    \end{equation*} The above bound again couples the step-size and the clipping radius, however, this time the step-size decays at a strictly faster rate, ensuring that the consensus gap decays at a strictly faster rate than the leading term. As such, Lemma \ref{lm:consensus-bound} provides a more fine-grained control of the consensus gap and is crucial to achieving improved rates. However, Lemma \ref{lm:consensus-crude} is still useful, see, e.g., the proof of Lemma \ref{lm:desirable-event} ahead.

\label{lm:freedman}
    Let $\{X_t\}_{t \in \mathbb{N}}$ be a martingale difference sequence such that for some $a > 0$ and all $t \in \mathbb{N}$ we have $|X_t| \leq a$ almost surely, and let $\sigma^2_t = \mathbb{E}[X_t^2\:|\: X_1,\ldots,X_{t-1}]$. Then for any $b,c > 0$ and $T \geq 1$
    \begin{equation*}
        \mathbb{P}\Big(\Big|\sum_{t \in [T]}X_t\Big| > b \text{ and } \sum_{t \in [T]}\sigma^2_t \leq c \Big) \leq 2\exp\bigg(-\frac{b^2}{2c + 2ab/3} \bigg).
    \end{equation*}

\label{lm:descent-sharp}
    Let Assumptions \ref{asmpt:network}-\ref{asmpt:bdd-het} hold. If the step-size satisfies $\alpha \leq \min\Big\{\frac{1}{2L}, \frac{1-\lambda^2}{8\lambda LB\sqrt{3}} \Big\}$, then for any $T \geq 1$, we have
    \begin{align*}
        \frac{\alpha}{16n}&\sum_{t \in [T]}\sum_{i \in [n]}\|\nabla f(x^t_i)\|^2 \leq \Delta_1 - \Delta_{T+1} - \alpha\sum_{t \in [T]}\langle \nabla f(\overline{x}^t), \widehat{g}^t_u\rangle + 2\alpha^2L\sum_{t \in [T]}\|\widehat{g}^t_u\|^2 \\
        &+ 2\alpha\sum_{t \in [T]}\|\widehat{g}^t_b\|^2 + \frac{12\alpha^3\lambda^2L^2A^2T}{(1-\lambda^2)^2} + \frac{12\alpha^3\lambda^2L^2}{n(1-\lambda^2)^2}\sum_{t \in [T]}\sum_{i \in [n]}\big(\|\widetilde{g}^t_{i,b}\|^2 + \|\widetilde{g}^t_{i,u}\|^2\big),
    \end{align*}

\label{lm:desirable-event}
    Let Assumptions \ref{asmpt:network}-\ref{asmpt:noise} hold and let the step-size and clipping threshold be chosen as $\gamma = \max\Big\{2A + 4B\sqrt{L\Delta_1} + \frac{2\lambda L\sqrt{n}}{1-\lambda}, (nT)^{\frac{1}{3p-2}} \Big\} $ and $\alpha = \min\Big\{\frac{1}{2L}, \frac{1-\lambda^2}{8\lambda LB\sqrt{3}}, \frac{1-\lambda^2}{\lambda L\sqrt{6}}, \frac{(1-\lambda^2)^2}{6\lambda^2L}, \linebreak \frac{(1-\lambda^2)^{2/3}\Delta_1^{1/3}}{2(\lambda LA)^{2/3}T^{1/3}\sqrt[3]{12}}, \frac{C_1}{\gamma}n^{\frac{2p-1}{3p-2}}T^{\frac{1-p}{3p-2}}, \frac{C_2}{\gamma^{2/3}}n^{\frac{p}{3(3p-2)}}T^{\frac{2(1-p)}{3(3p-2)}},\frac{C_3}{\gamma} \Big\}$, where $C_1 = \min\Big\{\frac{\Delta_1}{64\sigma^{2p}}, \linebreak \frac{\sqrt{\Delta_1}}{192\log\big(\frac{6T}{\delta}\big)\sigma^{p/2}\sqrt{2L}} \Big\}$, $C_2 \leq \frac{\Delta_1^{1/3}(1-\lambda^2)^{2/3}}{12\sigma^{p/3}\lambda^{2/3}L^{2/3}}$ and $C_3 = \min\Big\{1,\frac{3\sqrt{\Delta_1}}{64\log\big(\frac{6T}{\delta}\big)\sqrt{2L}}\Big\}$, for $\delta \in (0,1)$. For any $N \in [T+1]$, let $\Gamma_N$ be the event that, for all $t \in [N]$ 
    \begin{align*}
        &- \alpha\sum_{k \in [t-1]}\langle \nabla f(\overline{x}^k), \widehat{g}^k_u\rangle + 2\alpha^2L\sum_{k \in [t-1]}\|\widehat{g}^k_u\|^2 + 2\alpha\sum_{k \in [t-1]}\|\widehat{g}^k_b\|^2 \\
        &+ \frac{12\alpha^3\lambda^2L^2A^2T}{(1-\lambda^2)^2} + \frac{12\alpha^3\lambda^2L^2}{n(1-\lambda^2)^2}\sum_{k \in [t-1]}\sum_{i \in [n]}\big(\|\widetilde{g}^k_{i,b}\|^2 + \|\widetilde{g}^k_{i,u}\|^2\big) \leq \Delta_1.
    \end{align*} It then holds that $\mathbb{P}(\Gamma_N) \geq 1 - \frac{(N-1)\delta}{T}$. Moreover, on the event $\Gamma_N$ we have $\|\nabla f_i(x^t_i)\| \leq \frac{\gamma}{2}$, for all $i \in [n]$ and $t \in [N]$.

Let Assumptions \ref{asmpt:network}-\ref{asmpt:noise} hold. If for any $T \geq 1$ and $\delta \in (0,1)$, the clipping threshold and the step-size are chosen as $\gamma = \max\Big\{2A + 4B\sqrt{L\Delta_1} + \frac{2\lambda L\sqrt{n}}{1-\lambda}, (nT)^{\frac{1}{3p-2}} \Big\}$ and $\alpha = \min\Big\{\frac{1}{2L}, \frac{1-\lambda^2}{8\lambda LB\sqrt{3}}, \frac{1-\lambda^2}{\lambda L\sqrt{6}}, \frac{(1-\lambda^2)^2}{6\lambda^2L}, \frac{(1-\lambda^2)^{2/3}\Delta_1^{1/3}}{2(\lambda LA)^{2/3}T^{1/3}\sqrt[3]{12}}, \frac{C_1}{\gamma}n^{\frac{2p-1}{3p-2}}T^{\frac{1-p}{3p-2}},\frac{C_2}{\gamma^{2/3}}n^{\frac{p}{3(3p-2)}}T^{\frac{2(1-p)}{3(3p-2)}},\frac{C_3}{\gamma} \Big\}$, where $C_1 = \min\Big\{\frac{\Delta_1}{64\sigma^{2p}}, \frac{\sqrt{\Delta_1}}{192\log\big(\frac{6T}{\delta}\big)\sigma^{p/2}\sqrt{2L}} \Big\}$, $C_2 = \frac{\Delta_1^{1/3}(1-\lambda^2)^{2/3}}{12\sigma^{p/3}\lambda^{2/3}L^{2/3}}$ and $C_3 = \min\Big\{1,\frac{3\sqrt{\Delta_1}}{64\log\big(\frac{6T}{\delta}\big)\sqrt{2L}}\Big\}$, then with probability at least $1 - \delta$
    \begin{align*}
        \frac{1}{nT}\sum_{t \in [T]}\sum_{i \in [n]}\|\nabla f(x^t_i)\|^2 = \widetilde{\mathcal{O}}\Bigg(\max\Bigg\{(nT)^{\frac{2(1-p)}{3p-2}}, \frac{n^{\frac{1}{3p-2}}}{T^{\frac{3(p-1)}{3p-2}}}, \frac{n^{\frac{-p}{6p-4}}T^{\frac{1-2p}{3p-2}}}{(1-\lambda)},\\ \frac{n^{\frac{2(p-1)}{3(3p-2)}}}{(1-\lambda)^{\frac{4}{3}}T^{\frac{7p-4}{3(3p-2)}}}, \frac{n^{\frac{2-p}{3(3p-2)}}}{(1-\lambda^2)^{\frac{2}{3}}T^{\frac{7p-6}{3(3p-2)}}}, \frac{T^{-2/3}}{(1-\lambda^2)^{2/3}}, \frac{T^{-1}}{(1-\lambda^2)^2}, \frac{\sqrt{n}T^{-1}}{1-\lambda} \Bigg\}\Bigg).
    \end{align*}

Let Assumptions \ref{asmpt:network}-\ref{asmpt:noise} hold. If for any $T \geq 2$, the clipping threshold and the step-size are chosen as $\gamma = \max\Big\{2A + 4B\sqrt{L\Delta_1} + \frac{2\lambda L\sqrt{n}}{1-\lambda}, (nT)^{\frac{1}{3p-2}} \Big\}$ and $\alpha = \min\Big\{\frac{1}{2L}, \frac{1-\lambda^2}{8\lambda LB\sqrt{3}}, \frac{1-\lambda^2}{\lambda L\sqrt{6}}, \linebreak \frac{(1-\lambda^2)^2}{6\lambda^2L}, \frac{(1-\lambda^2)^{2/3}\Delta_1^{1/3}}{2(\lambda LA)^{2/3}T^{1/3}\sqrt[3]{12}}, \frac{C_1}{\gamma}n^{\frac{2p-1}{3p-2}}T^{\frac{1-p}{3p-2}},\frac{C_2}{\gamma^{2/3}}n^{\frac{p}{3(3p-2)}}T^{\frac{2(1-p)}{3(3p-2)}},\frac{C_3}{\gamma} \Big\}$, where $C_1 = \min\Big\{\frac{\Delta_1}{64\sigma^{2p}}, \linebreak \frac{\sqrt{\Delta_1}}{192\log(6n^4T^5)\sigma^{p/2}\sqrt{2L}} \Big\}$, $C_2 = \frac{\Delta_1^{1/3}(1-\lambda^2)^{2/3}}{12\sigma^{p/3}\lambda^{2/3}L^{2/3}}$ and $C_3 = \min\Big\{1,\frac{3\sqrt{\Delta_1}}{64\log(6n^4T^5)\sqrt{2L}}\Big\}$, then
    \begin{align*}
        \frac{1}{nT}\sum_{t \in [T]}\sum_{i \in [n]}\mathbb{E}\|\nabla f(x^t_i)\|^2 = \widetilde{\mathcal{O}}\Bigg(\max\Bigg\{(nT)^{\frac{2(1-p)}{3p-2}}, \frac{n^{\frac{1}{3p-2}}}{T^{\frac{3(p-1)}{3p-2}}}, \frac{n^{\frac{-p}{6p-4}}T^{\frac{1-2p}{3p-2}}}{(1-\lambda)},\\ \frac{n^{\frac{2(p-1)}{3(3p-2)}}}{(1-\lambda)^{\frac{4}{3}}T^{\frac{7p-4}{3(3p-2)}}}, \frac{n^{\frac{2-p}{3(3p-2)}}}{(1-\lambda^2)^{\frac{2}{3}}T^{\frac{7p-6}{3(3p-2)}}}, \frac{T^{-2/3}}{(1-\lambda^2)^{2/3}}, \frac{T^{-1}}{(1-\lambda^2)^2}, \frac{\sqrt{n}T^{-1}}{1-\lambda} \Bigg\}\Bigg).
    \end{align*}

For any $T \geq 2$ and $\delta \in (0,1)$, denote by $G^T_\delta \coloneqq \frac{1}{nT}\sum_{t \in [T]}\sum_{i \in [n]}\|\nabla f(x^t_i(\delta))\|^2$ and let $M^T_\delta =  \widetilde{\mathcal{O}}\Big(\max\Big\{(nT)^{\frac{2(1-p)}{3p-2}}, \frac{n^{\frac{1}{3p-2}}}{T^{\frac{3(p-1)}{3p-2}}}, \frac{n^{\frac{-p}{6p-4}}T^{\frac{1-2p}{3p-2}}}{(1-\lambda)},\frac{n^{\frac{2(p-1)}{3(3p-2)}}}{(1-\lambda)^{\frac{4}{3}}T^{\frac{7p-4}{3(3p-2)}}}, \frac{n^{\frac{2-p}{3(3p-2)}}}{(1-\lambda^2)^{\frac{2}{3}}T^{\frac{7p-6}{3(3p-2)}}}, \frac{T^{-2/3}}{(1-\lambda^2)^{2/3}}, \linebreak \frac{T^{-1}}{(1-\lambda^2)^2}, \frac{\sqrt{n}T^{-1}}{1-\lambda} \Big\}\Big)$, noting that, for any $\delta \in (0,1)$, we have
    \begin{align}\label{eq:expectation-setup}
        \mathbb{E}[G^T_\delta] &= \mathbb{E}\big[G^T_\delta\big(\mathbb{I}_{\{G^T_\delta \leq M^T_\delta \}} + \mathbb{I}_{\{G^T_\delta > M^T_\delta \}}\big)\big] \stackrel{(i)}{\leq} \mathbb{E}\big[M^T_\delta\mathbb{I}_{\{G^T_\delta \leq M^T_\delta \}}\big] + \sqrt{\mathbb{E}\big[\big(G^T_\delta\big)^2\big]\mathbb{E}\big[\mathbb{I}^2_{\{G^T_\delta > M^T_\delta \}}\big]} \nonumber \\
        &= M^T_\delta\mathbb{P}\big(G^T_\delta \leq M^T_\delta \big) + \sqrt{\mathbb{E}\big[\big(G^T_\delta\big)^2\big]\mathbb{P}\big(G^T_\delta > M^T_\delta \big)} \stackrel{(ii)}{\leq} M^T_\delta + \sqrt{\delta\mathbb{E}\big[\big(G^T_\delta\big)^2\big]},
    \end{align} where $(i)$ follows from H\"{o}lder's inequality, while $(ii)$ follows from Theorem \ref{thm:non-cvx-hp}. We now proceed to bound the term $G^T_\delta$. To that end, first note that for any $t \geq 1$, it holds that
    \begin{align}\label{eq:iterate-bdd}
        \|{\mathbf x^{t}} - {\mathbf x}^1\| &= \|\mathbf{W}({\mathbf x^{t-1}} - {\mathbf x}^1 - \alpha{\widetilde{\mathbf g}^{t}})\| \leq \|\mathbf{W}({\mathbf x^{t-1}} - {\mathbf x}^1)\| + \alpha\|\mathbf{W}{\widetilde{\mathbf g}^{t}}\| \nonumber \\ 
        &\leq \|{\mathbf x^{t-1}} - {\mathbf x}^1\| + \alpha\gamma\sqrt{n} \leq \ldots \leq \alpha\gamma(t-1)\sqrt{n} \leq \alpha\gamma t\sqrt{n},
    \end{align} where the second inequality follows from $\|\mathbf{W}\| \leq 1$ and $\|{\widetilde{\mathbf g}^{t}}\| \leq \gamma\sqrt{n}$. From the definition of $G^T_\delta$, we then get
    \begin{equation*}
        G^T_{\delta} \leq \frac{2}{n}\sum_{i \in [n]}\|\nabla f(x_i^1)\|^2 + \frac{2L^2}{nT}\sum_{t \in [T]}\|{\mathbf x^{t}} - {\mathbf x}^1\|^2 \leq 2\nabla_1 + \frac{2\alpha^2\gamma^2L^2}{T}\sum_{t \in [T]}t^2 \leq 2\nabla_1 + 2\alpha^2\gamma^2L^2T^2, 
    \end{equation*} where the second inequality follows from \eqref{eq:iterate-bdd} and the fact that agents have an identical initialization. Plugging this into \eqref{eq:expectation-setup}, we get
    \begin{equation}
        \mathbb{E}\big[G_{\delta}^T\big] \leq M_\delta^T + 2(\nabla_1 + \alpha^2\gamma^2L^2T^2)\delta^{1/2} \leq M_\delta^T + 2\bigg(\nabla_1 + C_1^2L^2(nT)^{\frac{2(2p-1)}{3p-2}}\bigg)\delta^{1/2},
    \end{equation} where the second inequality follows from the choice of $\alpha$ and $\gamma$. Choosing $\delta = (nT)^{-4} \in (0,1)$, it follows that 
    \begin{equation*}
        \mathbb{E}\big[G^T_\delta\big] \leq M_{\delta}^T + \frac{2\nabla_1}{n^2T^2} + \frac{C_1^2L^2}{(nT)^{\frac{2(p-1)}{3p-2}}} = \widetilde{\mathcal{O}}\big(M_\delta^T\big).
    \end{equation*}
